<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\Route;use Illuminate\Support\Facades\Schema;
class WarehouseV2HardeningCheckCommand extends Command{protected $signature='warehouse:v2-hardening-check';protected $description='Validasi instalasi hardening Warehouse v2';public function handle():int{$tables=['wh_go_live_runs','wh_go_live_check_results','wh_operation_locks','wh_reversal_requests'];$routes=['api/v1/warehouse/hardening/dashboard','api/v1/warehouse/hardening/go-live-runs','api/v1/warehouse/hardening/reversals'];$missing=array_values(array_filter($tables,fn($t)=>!Schema::hasTable($t)));$rm=array_values(array_filter($routes,fn($u)=>!collect(Route::getRoutes())->contains(fn($r)=>$r->uri()===$u)));$ok=!$missing&&!$rm;$this->table(['Check','Result'],[['Missing tables',$missing?implode(', ',$missing):'-'],['Missing routes',$rm?implode(', ',$rm):'-'],['Status',$ok?'PASSED':'FAILED']]);return$ok?self::SUCCESS:self::FAILURE;}}
